package local.remote;
import java.util.*;import java.nio.file.*;import java.lang.reflect.*;import com.google.gson.*;import com.mojang.authlib.GameProfile;
import net.neoforged.fml.common.Mod;import net.neoforged.neoforge.common.NeoForge;import net.neoforged.neoforge.event.tick.ServerTickEvent;import net.neoforged.neoforge.event.server.ServerStartedEvent;
import net.minecraft.resources.Identifier;import net.minecraft.server.level.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.ai.attributes.Attributes;import net.minecraft.world.item.*;import net.minecraft.world.effect.*;import net.minecraft.world.phys.Vec3;import net.minecraft.world.level.GameType;
import net.spell_engine.entity.WarriorRules;import net.spell_engine.internals.*;
import dev.betterparty.party.*;
@Mod("remote_spatial_probe") public class RemoteServerProbe {
 static final Path DIR=Path.of("../exchange");static final Gson G=new Gson();net.minecraft.server.MinecraftServer server;ServerPlayer p,caster,secondCaster;LivingEntity target;UUID partyId=UUID.randomUUID();Map<UUID,Party> parties;Map<UUID,UUID> members;Set<String> handled=new HashSet<>();
 static Object field(Object o,String n)throws Exception{var f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
 public RemoteServerProbe(){NeoForge.EVENT_BUS.addListener((ServerStartedEvent e)->{server=e.getServer();try{Files.createDirectories(DIR);Files.writeString(DIR.resolve("ready"),"ready");}catch(Exception x){throw new RuntimeException(x);}});NeoForge.EVENT_BUS.addListener(this::tick);}
 void equipCurio(boolean titan){var inv=top.theillusivec4.curios.api.CuriosApi.getCuriosInventory(p).orElseThrow();var stacks=inv.getCurios();boolean added=false;for(var entry:stacks.entrySet()){var handler=entry.getValue().getStacks();for(int i=0;i<handler.getSlots();i++){if(handler.getStackInSlot(i).is(com.cozary.nameless_trinkets.init.ModItems.TITANS_MARK.get()))handler.setStackInSlot(i,ItemStack.EMPTY);if(titan&&!added){handler.setStackInSlot(i,new ItemStack(com.cozary.nameless_trinkets.init.ModItems.TITANS_MARK.get()));added=true;}}}if(titan&&!added)throw new AssertionError("No Curios test slot available");}
 @SuppressWarnings("unchecked") void init()throws Exception{
  p=server.getPlayerList().getPlayers().getFirst();var w=p.level();p.setGameMode(GameType.SURVIVAL);p.getAbilities().invulnerable=false;p.setInvulnerable(false);p.getFoodData().setFoodLevel(20);p.getAttribute(Attributes.MAX_HEALTH).setBaseValue(1000);p.setHealth(1000);
  for(int x=-20;x<=20;x++)for(int z=-3;z<=14;z++){w.setBlock(new net.minecraft.core.BlockPos(x,99,z),net.minecraft.world.level.block.Blocks.STONE.defaultBlockState(),3);for(int y=100;y<107;y++)w.setBlock(new net.minecraft.core.BlockPos(x,y,z),net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),3);}
  caster=net.neoforged.neoforge.common.util.FakePlayerFactory.get(w,new GameProfile(UUID.randomUUID(),"WallCaster"));caster.setPos(0,100,0);caster.setHealth(caster.getMaxHealth());caster.setGameMode(GameType.SURVIVAL);
  var manager=PartyManager.forServer(server);parties=(Map<UUID,Party>)field(manager,"parties");members=(Map<UUID,UUID>)field(manager,"playerParties");
 }
 void party(boolean in)throws Exception{var manager=PartyManager.forServer(server);var bridge=field(manager,"vanillaTeamBridge");var previous=parties.get(partyId);if(previous!=null){var remove=bridge.getClass().getDeclaredMethod("removeParty",Party.class);remove.setAccessible(true);remove.invoke(bridge,previous);}var party=new Party(partyId);party.addMember(new PartyMember(caster.getUUID(),"WallCaster",PartyRole.LEADER));if(in)party.addMember(new PartyMember(p.getUUID(),"PaladinProbe",PartyRole.MEMBER));parties.put(partyId,party);members.put(caster.getUUID(),partyId);if(in)members.put(p.getUUID(),partyId);else members.remove(p.getUUID());var sync=bridge.getClass().getDeclaredMethod("syncParty",Party.class);sync.setAccessible(true);sync.invoke(bridge,party);}
 JsonObject action(JsonObject request)throws Exception{
  String op=request.get("op").getAsString();var result=new JsonObject();if(op.equals("init")){init();result.addProperty("ok",true);return result;}
  if(p==null)throw new AssertionError("not initialized");var w=p.level();
  if(op.startsWith("wall_")){
   if(op.equals("wall_join")){party(true);}else if(op.equals("wall_leave")||op.equals("wall_kick")){party(false);}else if(op.equals("wall_disband")){parties.remove(partyId);members.remove(p.getUUID());members.remove(caster.getUUID());}else if(op.equals("wall_end")){PaladinUltimates.end(caster,PaladinUltimates.End.RELEASE);if(secondCaster!=null)PaladinUltimates.end(secondCaster,PaladinUltimates.End.RELEASE);}else{
    PaladinUltimates.end(caster,PaladinUltimates.End.CLEANUP);if(secondCaster!=null)PaladinUltimates.end(secondCaster,PaladinUltimates.End.CLEANUP);p.removeAllEffects();equipCurio(false);p.getAttribute(Attributes.SCALE).setBaseValue(1);p.refreshDimensions();party(op.equals("wall_party"));caster.setPos(0,100,0);caster.setHealth(caster.getMaxHealth());PaladinUltimates.startChannel(caster,w.getGameTime());
    // A synthetic owner is not in the world's entity lookup; supply the native owner's cache explicitly.
    for(var wall:PurgatoryBoundary.active(w))if(!wall.isRemoved()){var cached=wall.getClass().getDeclaredField("cachedOwner");cached.setAccessible(true);cached.set(wall,caster);}
   }
   if(op.equals("wall_overlap")){party(true);secondCaster=net.neoforged.neoforge.common.util.FakePlayerFactory.get(w,new GameProfile(UUID.randomUUID(),"SecondCaster"));secondCaster.setPos(-3,100,0);secondCaster.setHealth(secondCaster.getMaxHealth());PaladinUltimates.startChannel(secondCaster,w.getGameTime());for(var wall:PurgatoryBoundary.active(w))if(!wall.isRemoved()&&wall.getOwner()==null){var cached=wall.getClass().getDeclaredField("cachedOwner");cached.setAccessible(true);cached.set(wall,secondCaster);}}
   if(op.equals("wall_death")){caster.setHealth(0);PurgatoryBoundary.tick(PurgatoryBoundary.active(w).getFirst());}
   double x=request.has("x")?request.get("x").getAsDouble():11.4;double y=request.has("y")?request.get("y").getAsDouble():100;p.teleportTo(w,x,y,0,Set.of(),0,0,true);p.setDeltaMovement(Vec3.ZERO);
   result.addProperty("walls",PurgatoryBoundary.active(w).size());result.addProperty("ally",PartyRules.allies(caster,p));var debug=new JsonArray();for(var wall:PurgatoryBoundary.active(w)){var d=new JsonObject();d.addProperty("removed",wall.isRemoved());d.addProperty("alive",wall.isAlive());d.addProperty("owner",String.valueOf(wall.getOwner()));d.addProperty("casterChannel",PaladinUltimates.channelOf(caster)!=null);debug.add(d);}result.add("wallState",debug);
  }else if(op.equals("reach")){
   PaladinUltimates.end(caster,PaladinUltimates.End.CLEANUP);if(secondCaster!=null)PaladinUltimates.end(secondCaster,PaladinUltimates.End.CLEANUP);party(false);p.removeAllEffects();equipCurio(false);p.getAttribute(Attributes.SCALE).setBaseValue(request.has("scale")?request.get("scale").getAsDouble():1);p.getAttribute(Attributes.ATTACK_DAMAGE).setBaseValue(10);p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(request.has("hammer")?net.minecraft.core.registries.BuiltInRegistries.ITEM.getValue(Identifier.parse("arsenal:hammer_of_destiny")):Items.IRON_SWORD));p.refreshDimensions();p.teleportTo(w,0,100,0,Set.of(),0,0,true);
   var category=net.puffish.skillsmod.api.SkillsAPI.getCategory(Identifier.parse("skill_tree_rpgs:class_skills")).orElseThrow();category.unlock(p);category.resetSkills(p);category.setExtraPoints(p,1000);p.setHealth(p.getMaxHealth());if(request.has("enrage")){category.getSkill("ENRAGE_SKILL_ID").orElseThrow().unlock(p);p.setHealth(p.getMaxHealth()*.1f);}if(request.has("titan"))equipCurio(true);
   if(target!=null)target.discard();target=EntityTypes.CREEPER.create(w,EntitySpawnReason.COMMAND);target.setNoGravity(true);((Mob)target).setNoAi(true);target.getAttribute(Attributes.MAX_HEALTH).setBaseValue(1000);target.getAttribute(Attributes.ARMOR).setBaseValue(0);target.setHealth(1000);target.setPos(0,100,request.get("distance").getAsDouble());w.addFreshEntity(target);
  }else if(op.equals("prepare_attack")){if(target==null)throw new AssertionError("target");target.invulnerableTime=0;target.setHealth(1000);p.setOnGround(true);p.setDeltaMovement(Vec3.ZERO);var access=(net.spell_engine.mixin.thirdtier.RogueAttackAccess)p;access.rogueAttackStrength(100);access.rogueSwapStrength(100);}
  else if(op.equals("facts")){}
  else if(op.equals("finish")){server.halt(false);}
  else throw new AssertionError(op);
  result.addProperty("x",p.getX());result.addProperty("y",p.getY());result.addProperty("z",p.getZ());result.addProperty("scale",p.getScale());result.addProperty("range",p.entityInteractionRange());result.addProperty("blockRange",p.blockInteractionRange());result.addProperty("expectedRange",net.bettercombat.logic.PlayerAttackHelper.getRangeForItem(p,p.getMainHandItem())*net.bettercombat.BetterCombatMod.config.getAttackRangeMultiplierForScale(p.getScale()));
  if(target!=null&&!target.isRemoved()){result.addProperty("target",target.getId());result.addProperty("health",target.getHealth());result.addProperty("nativeWithin",p.isWithinAttackRange(p.getMainHandItem(),target.getBoundingBox(),3));result.addProperty("targetZ",target.getZ());}
  return result;
 }
 void tick(ServerTickEvent.Post event){if(server==null)return;try{
  try(var files=Files.newDirectoryStream(DIR,"request-*.json")){for(var file:files){String key=file.getFileName().toString();if(!handled.add(key))continue;var request=JsonParser.parseString(Files.readString(file)).getAsJsonObject();String token=request.get("token").getAsString();JsonObject response;try{response=action(request);}catch(Throwable t){t.printStackTrace();response=new JsonObject();response.addProperty("error",t.toString());}response.addProperty("token",token);response.addProperty("op",request.get("op").getAsString());Files.writeString(DIR.resolve("response-"+token+".tmp"),G.toJson(response));Files.move(DIR.resolve("response-"+token+".tmp"),DIR.resolve("response-"+token+".json"),StandardCopyOption.ATOMIC_MOVE);}}
 }catch(Throwable t){t.printStackTrace();}}
}
